raw_shacl_shapes:
@prefix sh: <http://www.w3.org/ns/shacl#> .
@prefix site: <http://sophia.ai/site#> .

site:DefinitionIntegrityShape a sh:NodeShape ;
    sh:targetClass site:SiteDefinition ;
    sh:property [ sh:path site:layoutSeedSha256 ; sh:pattern "^[a-f0-9]{64}$" ; sh:severity sh:Violation ] .

site:ContentSourceIntegrityShape a sh:NodeShape ;
    sh:targetClass site:ContentSource ;
    sh:property [ sh:path site:authMode ; sh:in ( "none" "dev" "cognito" "service" ) ; sh:severity sh:Violation ] ;
    sh:property [ sh:path site:liveness ; sh:in ( "static" "poll" "push" ) ; sh:severity sh:Violation ] .

site:PublicationRouteIntegrityShape a sh:NodeShape ;
    sh:targetClass site:PublicationRoute ;
    sh:property [ sh:path site:ownerPrincipal ; sh:pattern "^(user|agent|service|organization):[A-Za-z0-9_.@:-]{1,192}$" ; sh:severity sh:Violation ] ;
    sh:property [ sh:path site:graphId ; sh:pattern "^[a-z0-9]([a-z0-9-]{0,38}[a-z0-9])?$" ; sh:severity sh:Violation ] ;
    sh:property [ sh:path site:pathPrefix ; sh:pattern "^/" ; sh:severity sh:Violation ] ;
    sh:property [ sh:path site:publicationState ; sh:in ( "unlisted" "published" "retired" ) ; sh:severity sh:Violation ] ;
    sh:or (
        [ sh:property [ sh:path site:publicationState ; sh:in ( "unlisted" "retired" ) ] ]
        [ sh:property [ sh:path site:publicationState ; sh:hasValue "published" ] ;
          sh:property [ sh:path site:approvedBy ; sh:minCount 1 ; sh:pattern "^user:[A-Za-z0-9_.@:-]{1,192}$" ] ;
          sh:property [ sh:path site:approvedAt ; sh:minCount 1 ] ]
    ) .
